from __future__ import annotations

import sys
import unittest
from pathlib import Path
from unittest.mock import patch


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import build_rules  # noqa: E402


class SKKMarkerDetectionTests(unittest.TestCase):
    def test_dynamic_marker_is_filtered_and_regular_skk_domains_remain(self) -> None:
        current_marker = "7h15_ru1353t_1s_m4d3_by_5ukk4w.skk.moe"
        legacy_marker = "7h1s_rul35et_i5_mad3_by_5ukk4w-ruleset.skk.moe"
        lines = [
            "# generated by SKK",
            f"DOMAIN,{current_marker}",
            "DOMAIN,cdn.skk.moe",
            "DOMAIN,ruleset.skk.moe",
            "DOMAIN-SUFFIX,skk.moe",
            f"DOMAIN,{legacy_marker}",
            f"DOMAIN,{current_marker}",
        ]
        config = {
            "source_marker_domains": [legacy_marker],
            "sources": {
                "skk": {
                    "kind": "non-ip",
                    "urls": [
                        "https://raw.githubusercontent.com/SukkaLab/ruleset.skk.moe/master/List/non_ip/global.conf"
                    ],
                }
            },
        }

        with patch.object(build_rules, "read_configured_lines", return_value=lines):
            loaded, _ = build_rules.load_source_rules(config)

        values = {rule.value for rule in loaded["skk"]}
        self.assertNotIn(current_marker, values)
        self.assertNotIn(legacy_marker, values)
        self.assertIn("cdn.skk.moe", values)
        self.assertIn("ruleset.skk.moe", values)
        self.assertIn("skk.moe", values)

    def test_bare_domainset_marker_is_detected(self) -> None:
        marker = "7h15_ru1353t_1s_m4d3_by_5ukk4w.skk.moe"
        config = {
            "source_marker_domains": [],
            "sources": {
                "skk-domainset": {
                    "kind": "domainset",
                    "urls": [
                        "https://raw.githubusercontent.com/SukkaLab/ruleset.skk.moe/master/List/domainset/cdn.conf"
                    ],
                }
            },
        }

        with patch.object(
            build_rules,
            "read_configured_lines",
            return_value=[marker, ".cdn.skk.moe", "img.skk.moe"],
        ):
            loaded, _ = build_rules.load_source_rules(config)

        values = {rule.value for rule in loaded["skk-domainset"]}
        self.assertNotIn(marker, values)
        self.assertIn("cdn.skk.moe", values)
        self.assertIn("img.skk.moe", values)

    def test_non_skk_source_does_not_apply_dynamic_marker_detection(self) -> None:
        domain = "first-rule.skk.moe"
        config = {
            "source_marker_domains": [],
            "sources": {
                "other": {
                    "kind": "non-ip",
                    "urls": ["https://example.com/rules.conf"],
                }
            },
        }

        with patch.object(
            build_rules,
            "read_configured_lines",
            return_value=[f"DOMAIN,{domain}"],
        ):
            loaded, _ = build_rules.load_source_rules(config)

        self.assertEqual([domain], [rule.value for rule in loaded["other"]])


class RankedSourceTests(unittest.TestCase):
    def test_keeps_only_ranked_sites_listed_by_the_source(self) -> None:
        config = {
            "source_marker_domains": [],
            "sources": {
                "direct": {
                    "kind": "domainset",
                    "urls": ["https://example.com/direct.txt"],
                    "keep_ranked": {"urls": ["https://example.com/top-1m.csv"]},
                }
            },
        }
        lines = {
            "direct": ["popular.com", ".cdn.popular.com", "obscure.com", "cn-node.apple.com"],
            "direct.keep_ranked": ["1,apple.com", "2,popular.com\r", "3,unlisted.com"],
        }

        with patch.object(
            build_rules,
            "read_configured_lines",
            side_effect=lambda source_id, _: lines[source_id],
        ):
            loaded, skipped = build_rules.load_source_rules(config)

        self.assertEqual(["popular.com", "cdn.popular.com"], [rule.value for rule in loaded["direct"]])
        self.assertEqual(2, skipped["direct"]["UNRANKED"])


class ListedRuleFilterTests(unittest.TestCase):
    def test_drops_listed_domains_and_their_subdomains_but_keeps_parents(self) -> None:
        rules = [
            build_rules.Rule("DOMAIN-SUFFIX", "cn"),
            build_rules.Rule("DOMAIN-SUFFIX", "mi.com"),
            build_rules.Rule("DOMAIN-SUFFIX", "broker.com"),
            build_rules.Rule("DOMAIN", "api.broker.com"),
            build_rules.Rule("DOMAIN-KEYWORD", "broker"),
        ]
        listed = [
            build_rules.Rule("DOMAIN-SUFFIX", "broker.com"),
            build_rules.Rule("DOMAIN-SUFFIX", "c.mi.com"),
            build_rules.Rule("DOMAIN-SUFFIX", "blocked.cn"),
        ]

        kept = build_rules.drop_listed_rules(rules, listed)

        self.assertEqual(
            [("DOMAIN-SUFFIX", "cn"), ("DOMAIN-SUFFIX", "mi.com"), ("DOMAIN-KEYWORD", "broker")],
            [rule.key for rule in kept],
        )

    def test_output_can_exclude_rules_listed_by_a_built_output(self) -> None:
        source_rules = {
            "downloads": [
                build_rules.Rule("DOMAIN", "downloads.claude.ai"),
                build_rules.Rule("DOMAIN-SUFFIX", "cdn.hf.co"),
            ]
        }
        built_outputs = {"ai": [build_rules.Rule("DOMAIN-SUFFIX", "claude.ai")]}

        rules, _ = build_rules.collect_output_rules(
            "download",
            {"sources": ["downloads"], "exclude_listed_by": ["ai"]},
            source_rules,
            {},
            set(),
            built_outputs,
        )

        self.assertEqual([("DOMAIN-SUFFIX", "cdn.hf.co")], [rule.key for rule in rules])


class MihomoWildcardTests(unittest.TestCase):
    def test_partial_label_wildcards_move_from_domain_mrs_to_classical_regex(self) -> None:
        rules = [
            build_rules.Rule("DOMAIN-WILDCARD", "download*.mediafire.com"),
            build_rules.Rule("DOMAIN-WILDCARD", "ftp.??.debian.org"),
            build_rules.Rule("DOMAIN-WILDCARD", "*.example.com"),
            build_rules.Rule("DOMAIN-SUFFIX", "example.org"),
            build_rules.Rule("DOMAIN-KEYWORD", "keyword"),
        ]

        self.assertEqual(
            ["ftp.??.debian.org", "*.example.com", "+.example.org"],
            build_rules.mihomo_domain_lines(rules),
        )
        self.assertEqual(
            ["DOMAIN-KEYWORD,keyword", "DOMAIN-REGEX,^download.*\\.mediafire\\.com$"],
            build_rules.mihomo_classical_lines(rules),
        )


if __name__ == "__main__":
    unittest.main()
